//! Static registry ids (the 26.3 data generator's `registries.json`), for packets that write a registry entry by
//! number: particles, sounds, effects, attributes, menus and so on. Generated by `tools/gen_registries.mjs`;
//! entity types are in [`crate::entity_types`]. Data-driven registries (enchantments, trim materials, variants,
//! dimension types) are not here: their ids come from the configuration-state sync.

mod generated;

use std::collections::HashMap;
use std::sync::OnceLock;

use crate::{Error, VarInt, Wire};

pub use generated::*;

struct Index {
    names: Vec<&'static str>,
    ids: HashMap<&'static str, i32>,
}

/// One registry: names in id order.
pub struct Registry {
    pub key: &'static str,
    blob: &'static str,
    index: OnceLock<Index>,
}

impl Registry {
    const fn new(key: &'static str, blob: &'static str) -> Self {
        Self { key, blob, index: OnceLock::new() }
    }

    fn index(&self) -> &Index {
        self.index.get_or_init(|| {
            let names: Vec<&'static str> = self.blob.lines().collect();
            let ids = names.iter().enumerate().map(|(i, n)| (*n, i as i32)).collect();
            Index { names, ids }
        })
    }

    pub fn len(&self) -> usize {
        self.index().names.len()
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    pub fn name(&self, id: i32) -> Option<&'static str> {
        usize::try_from(id).ok().and_then(|i| self.index().names.get(i).copied())
    }

    /// The id of a full name such as `minecraft:speed`.
    pub fn id(&self, name: &str) -> Option<i32> {
        self.index().ids.get(name).copied()
    }

    /// Like [`Self::id`], also accepting a bare `speed` for the `minecraft` namespace.
    pub fn id_lenient(&self, name: &str) -> Option<i32> {
        self.id(name).or_else(|| if name.contains(':') { None } else { self.id(&format!("minecraft:{name}")) })
    }

    pub fn require(&self, name: &str) -> Result<i32, Error> {
        self.id_lenient(name).ok_or(Error::Invalid("registry entry"))
    }

    pub fn names(&self) -> impl Iterator<Item = &'static str> + '_ {
        self.index().names.iter().copied()
    }

    /// `ByteBufCodecs.registry`: the id as a VarInt.
    pub fn write_entry(&self, name: &str, out: &mut Vec<u8>) -> Result<(), Error> {
        VarInt(self.require(name)?).write(out);
        Ok(())
    }

    /// `Holder` by reference (`ByteBufCodecs.holder` with a registered entry): `id + 1`, 0 being an inline value.
    pub fn write_holder_ref(&self, name: &str, out: &mut Vec<u8>) -> Result<(), Error> {
        VarInt(self.require(name)? + 1).write(out);
        Ok(())
    }
}

